import "./Admin.css";
import { useEffect, useState, useCallback } from "react";

function Admin() {
  const [inquiries, setInquiries] = useState([]);
  const [search, setSearch] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const inquiriesPerPage = 5;

  const [services, setServices] = useState([]);
  const [serviceName, setServiceName] = useState("");
  const [documents, setDocuments] = useState("");
  const [price, setPrice] = useState("");
  const [duration, setDuration] = useState("");
  const [description, setDescription] = useState("");
  const [imageURL, setImageURL] = useState("");

  const [selectedFile, setSelectedFile] = useState(null);
  const [images, setImages] = useState([]);

  const [activeSection, setActiveSection] = useState(null); // "inquiries" | "services" | "slider" | "users" | null

  // ====== FIRST ADMIN REGISTRATION ======
  const [isAdminExists, setIsAdminExists] = useState(true);
  const [regUsername, setRegUsername] = useState("");
  const [regPassword, setRegPassword] = useState("");

  // ====== LOGIN / AUTH ======
  const [token, setToken] = useState(localStorage.getItem("admin_token") || "");
  const [loginUsername, setLoginUsername] = useState("");
  const [loginPassword, setLoginPassword] = useState("");
  const [otpUsername, setOtpUsername] = useState("");
  const [otpCode, setOtpCode] = useState("");
  const [otpRequested, setOtpRequested] = useState(false);
  const [authError, setAuthError] = useState("");

  // ====== CREATE USER (admin-only) ======
  const [newUserName, setNewUserName] = useState("");
  const [newUserPassword, setNewUserPassword] = useState("");
  const [newUserMobile, setNewUserMobile] = useState("");
  const [newUserEmail, setNewUserEmail] = useState("");

  const checkAdmin = useCallback(async () => {
    try {
      const res = await fetch("http://127.0.0.1:8000/check-admin");
      const data = await res.json();
      setIsAdminExists(data.exists);
    } catch (err) {
      console.error("Error checking admin:", err);
    }
  }, []);

  const registerAdmin = async () => {
    if (!regUsername || !regPassword) return alert("Enter username and password");
    try {
      const res = await fetch("http://127.0.0.1:8000/register-admin", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ username: regUsername, password: regPassword }),
      });

      const data = await res.json();
      if (res.ok) {
        alert("Admin registered successfully! Please login.");
        setIsAdminExists(true);
        setRegUsername("");
        setRegPassword("");
      } else {
        alert(data.detail || "Error");
      }
    } catch (err) {
      console.error("Error registering admin:", err);
      alert("Error registering admin");
    }
  };

  // ======= AUTH Helpers =======
  const saveToken = (tok) => {
    setToken(tok);
    localStorage.setItem("admin_token", tok);
  };

  const logout = () => {
    setToken("");
    localStorage.removeItem("admin_token");
    setActiveSection(null);
  };

  // Password login (OAuth2PasswordRequestForm expects form-url-encoded)
  const loginWithPassword = async () => {
    setAuthError("");
    if (!loginUsername || !loginPassword) {
      setAuthError("Enter username and password");
      return;
    }
    try {
      const formBody = new URLSearchParams();
      formBody.append("username", loginUsername);
      formBody.append("password", loginPassword);

      const res = await fetch("http://127.0.0.1:8000/login", {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: formBody.toString(),
      });
      const data = await res.json();
      if (res.ok && data.access_token) {
        saveToken(data.access_token);
        setLoginUsername("");
        setLoginPassword("");
        setAuthError("");
        alert("Login successful");
      } else {
        setAuthError(data.detail || "Login failed");
      }
    } catch (err) {
      console.error("Login error:", err);
      setAuthError("Login failed");
    }
  };

  // Request OTP for admin (calls /request-otp)
  const requestOtp = async (usernameToRequest) => {
    setAuthError("");
    if (!usernameToRequest) {
      setAuthError("Enter username first to request OTP");
      return;
    }
    try {
      const res = await fetch("http://127.0.0.1:8000/request-otp", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ username: usernameToRequest }),
      });
      const data = await res.json();
      if (res.ok) {
        setOtpRequested(true);
        setOtpUsername(usernameToRequest);
        // demo: server returns OTP
        if (data.otp) alert(`Demo OTP (server returned): ${data.otp}`);
        alert("OTP requested. Enter OTP to verify.");
      } else {
        setAuthError(data.detail || "OTP request failed");
      }
    } catch (err) {
      console.error("requestOtp err", err);
      setAuthError("OTP request failed");
    }
  };

  // Verify OTP for admin (/login-otp)
  const verifyOtpLogin = async () => {
    if (!otpUsername || !otpCode) return setAuthError("Enter username and OTP");
    try {
      const res = await fetch("http://127.0.0.1:8000/login-otp", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ username: otpUsername, otp: otpCode }),
      });
      const data = await res.json();
      if (res.ok && data.access_token) {
        saveToken(data.access_token);
        setOtpRequested(false);
        setOtpCode("");
        setOtpUsername("");
        setAuthError("");
        alert("Login via OTP successful");
      } else {
        setAuthError(data.detail || "OTP verify failed");
      }
    } catch (err) {
      console.error("verifyOtpLogin err", err);
      setAuthError("OTP verify failed");
    }
  };

  // Forgot password for admin (OTP flow)
  const forgotPasswordFlow = async () => {
    setAuthError("");
    const user = prompt("Enter admin username for forgot-password OTP:");
    if (!user) return;
    await requestOtp(user);
    const enteredOtp = prompt("Enter OTP sent to admin (demo):");
    if (!enteredOtp) return alert("No OTP entered");
    try {
      const res = await fetch("http://127.0.0.1:8000/login-otp", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ username: user, otp: enteredOtp }),
      });
      const data = await res.json();
      if (res.ok && data.access_token) {
        saveToken(data.access_token);
        alert("OTP verified. You are logged in.");
      } else {
        alert(data.detail || "OTP verification failed");
      }
    } catch (err) {
      console.error(err);
      alert("Error verifying OTP");
    }
  };

  // ======= INQUIRIES ==========
  const fetchInquiries = useCallback(async () => {
    try {
      const response = await fetch("http://127.0.0.1:8000/inquiries");
      const data = await response.json();
      setInquiries(data);
    } catch (error) {
      console.error("Error fetching inquiries:", error);
    }
  }, []);

  const deleteInquiry = async (id) => {
    try {
      const response = await fetch(`http://127.0.0.1:8000/inquiry/${id}`, {
        method: "DELETE",
      });
      if (response.ok) {
        alert("Inquiry deleted successfully!");
        fetchInquiries();
      } else {
        const err = await response.json();
        alert(err.detail);
      }
    } catch (error) {
      console.error("Error deleting inquiry:", error);
    }
  };

  // ======= SERVICES ==========
  const fetchServices = useCallback(async () => {
    try {
      const res = await fetch("http://127.0.0.1:8000/services");
      const data = await res.json();
      setServices(data);
    } catch (err) {
      console.error("Error fetching services:", err);
    }
  }, []);

  const addService = async () => {
    if (!serviceName || !documents || !price || !duration || !description) {
      alert("Please fill all fields");
      return;
    }
    try {
      const res = await fetch("http://127.0.0.1:8000/service", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          serviceName,
          documents,
          price,
          duration,
          description,
          imageURL,
        }),
      });
      if (res.ok) {
        alert("Service added successfully!");
        fetchServices();
        setServiceName("");
        setDocuments("");
        setPrice("");
        setDuration("");
        setDescription("");
        setImageURL("");
      }
    } catch (err) {
      console.error("Error adding service:", err);
    }
  };

  const deleteService = async (id) => {
    try {
      const res = await fetch(`http://127.0.0.1:8000/service/${id}`, {
        method: "DELETE",
      });
      if (res.ok) {
        alert("Service deleted successfully!");
        fetchServices();
      }
    } catch (err) {
      console.error("Error deleting service:", err);
    }
  };

  // ======= SLIDER IMAGES ==========
  const fetchImages = useCallback(async () => {
    try {
      const res = await fetch("http://127.0.0.1:8000/images");
      const data = await res.json();
      setImages(data.images || []);
    } catch (err) {
      console.error("Error fetching images:", err);
    }
  }, []);

  const handleUpload = async () => {
    if (!selectedFile) return alert("Select a file first!");
    const formData = new FormData();
    formData.append("file", selectedFile);

    await fetch("http://127.0.0.1:8000/upload-image", {
      method: "POST",
      body: formData,
    });

    alert("Image uploaded successfully!");
    fetchImages();
  };

  const handleDeleteImage = async (imageName) => {
    const confirmDelete = window.confirm("Are you sure to delete this image?");
    if (!confirmDelete) return;

    await fetch(`http://127.0.0.1:8000/delete-image/${imageName}`, {
      method: "DELETE",
    });

    alert("Image deleted successfully!");
    fetchImages();
  };

  // ======= PAGINATION ==========
  const indexOfLastInquiry = currentPage * inquiriesPerPage;
  const indexOfFirstInquiry = indexOfLastInquiry - inquiriesPerPage;

  const filteredInquiries = inquiries
    .filter(
      (inq) =>
        inq.name.toLowerCase().includes(search.toLowerCase()) ||
        inq.mobile.includes(search)
    )
    .sort((a, b) => new Date(b.date) - new Date(a.date));

  const currentInquiries = filteredInquiries.slice(
    indexOfFirstInquiry,
    indexOfLastInquiry
  );

  const totalPages = Math.ceil(filteredInquiries.length / inquiriesPerPage);

  const handleNext = () => {
    if (currentPage < totalPages) setCurrentPage(currentPage + 1);
  };
  const handlePrev = () => {
    if (currentPage > 1) setCurrentPage(currentPage - 1);
  };

  // ======= CREATE USER (admin-only) ======
  const createUser = async () => {
    if (!newUserName || !newUserPassword)
      return alert("Enter username & password for new user");
    try {
      const res = await fetch("http://127.0.0.1:8000/create-user", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          username: newUserName,
          password: newUserPassword,
          mobile: newUserMobile,
          email: newUserEmail,
        }),
      });
      const data = await res.json();
      if (res.ok) {
        alert("User created successfully");
        setNewUserName("");
        setNewUserPassword("");
        setNewUserMobile("");
        setNewUserEmail("");
      } else {
        alert(data.detail || "Create user failed");
      }
    } catch (err) {
      console.error("createUser err", err);
      alert("Create user failed");
    }
  };

  // ======= USE EFFECT ==========
  useEffect(() => {
    checkAdmin();
  }, [checkAdmin]);

  useEffect(() => {
    if (!token) return;
    if (activeSection === "inquiries") fetchInquiries();
    if (activeSection === "services") fetchServices();
    if (activeSection === "slider") fetchImages();
  }, [token, activeSection, fetchInquiries, fetchServices, fetchImages]);

  // ======= UI ==========

  // First admin registration (unchanged)
  if (!isAdminExists) {
    return (
      <div className="admin-container">
        <h2>Register First Admin</h2>
        <input
          type="text"
          placeholder="Username"
          value={regUsername}
          onChange={(e) => setRegUsername(e.target.value)}
        />
        <input
          type="password"
          placeholder="Password"
          value={regPassword}
          onChange={(e) => setRegPassword(e.target.value)}
        />
        <button onClick={registerAdmin}>Register</button>
      </div>
    );
  }

  // Admin exists but not logged in → Login screen
  if (!token) {
    return (
      <div className="admin-container">
        <h2>Admin Login</h2>

        <div style={{ marginBottom: 8 }}>
          <input
            type="text"
            placeholder="Username"
            value={loginUsername}
            onChange={(e) => setLoginUsername(e.target.value)}
          />
        </div>

        <div style={{ marginBottom: 8 }}>
          <input
            type="password"
            placeholder="Password"
            value={loginPassword}
            onChange={(e) => setLoginPassword(e.target.value)}
          />
        </div>

        <div style={{ display: "flex", gap: 8, marginBottom: 8, flexWrap: "wrap" }}>
          <button onClick={loginWithPassword}>Login</button>
          <button onClick={() => requestOtp(loginUsername)}>Request OTP</button>
          <button onClick={forgotPasswordFlow}>Forgot Password (OTP)</button>
        </div>

        {otpRequested && (
          <div style={{ marginBottom: 8 }}>
            <input
              type="text"
              placeholder="OTP"
              value={otpCode}
              onChange={(e) => setOtpCode(e.target.value)}
            />
            <button onClick={verifyOtpLogin}>Verify OTP</button>
          </div>
        )}

        {authError && (
          <div style={{ color: "red", marginTop: 8 }}>{authError}</div>
        )}

        <div style={{ marginTop: 12 }}>
          <small>
            Note: Login supports password or OTP (server returns OTP in demo).
          </small>
        </div>
      </div>
    );
  }

  // Logged-in admin → original dashboard
  return (
    <div className="admin-container">
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
        }}
      >
        <h1>Admin Dashboard</h1>
        <div>
          <button onClick={logout} style={{ marginRight: 8 }}>
            Logout
          </button>
          <button
            onClick={() => {
              alert("Logged in (token present).");
            }}
          >
            Token
          </button>
        </div>
      </div>

      {!activeSection && (
        <div className="admin-menu">
          <button onClick={() => setActiveSection("inquiries")}>
            📋 Manage Inquiries
          </button>
          <button onClick={() => setActiveSection("services")}>
            🛠 Manage Services
          </button>
          <button onClick={() => setActiveSection("slider")}>
            🖼 Manage Slider Images
          </button>
          <button onClick={() => setActiveSection("users")}>
            👥 Manage Users
          </button>
        </div>
      )}

      {/* INQUIRIES SECTION */}
      {activeSection === "inquiries" && (
        <div className="inquiries-section">
          <h2>Inquiries</h2>
          <button onClick={() => setActiveSection(null)}>⬅ Back</button>
          <input
            type="text"
            placeholder="Search by name or mobile..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
          {inquiries.length === 0 ? (
            <p>No inquiries found.</p>
          ) : (
            <>
              <table border="1" cellPadding="10">
                <thead>
                  <tr>
                    <th>Name</th>
                    <th>Email</th>
                    <th>Mobile</th>
                    <th>Message</th>
                    <th>Date</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {currentInquiries.map((inq) => (
                    <tr key={inq._id}>
                      <td>{inq.name}</td>
                      <td>{inq.email}</td>
                      <td>{inq.mobile}</td>
                      <td>{inq.message}</td>
                      <td>{new Date(inq.date).toLocaleString()}</td>
                      <td>
                        <button onClick={() => deleteInquiry(inq._id)}>
                          Delete
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              <div>
                <button onClick={handlePrev} disabled={currentPage === 1}>
                  Previous
                </button>
                <button
                  onClick={handleNext}
                  disabled={currentPage === totalPages}
                >
                  Next
                </button>
              </div>
            </>
          )}
        </div>
      )}

      {/* SERVICES SECTION */}
      {activeSection === "services" && (
        <div className="services-section">
          <h2>Manage Services</h2>
          <button onClick={() => setActiveSection(null)}>⬅ Back</button>

          <div>
            <input
              type="text"
              placeholder="Service Name"
              value={serviceName}
              onChange={(e) => setServiceName(e.target.value)}
            />
            <input
              type="text"
              placeholder="Documents Required"
              value={documents}
              onChange={(e) => setDocuments(e.target.value)}
            />
            <input
              type="text"
              placeholder="Price"
              value={price}
              onChange={(e) => setPrice(e.target.value)}
            />
            <input
              type="text"
              placeholder="Duration"
              value={duration}
              onChange={(e) => setDuration(e.target.value)}
            />
            <input
              type="text"
              placeholder="Description"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
            />
            <input
              type="text"
              placeholder="Image URL"
              value={imageURL}
              onChange={(e) => setImageURL(e.target.value)}
            />
            <button onClick={addService}>Add Service</button>
          </div>

          {services.length > 0 && (
            <table border="1" cellPadding="10">
              <thead>
                <tr>
                  <th>Service Name</th>
                  <th>Documents</th>
                  <th>Price</th>
                  <th>Duration</th>
                  <th>Description</th>
                  <th>Image</th>
                  <th>Action</th>
                </tr>
              </thead>
              <tbody>
                {services.map((s) => (
                  <tr key={s._id}>
                    <td>{s.serviceName}</td>
                    <td>{s.documents}</td>
                    <td>{s.price}</td>
                    <td>{s.duration}</td>
                    <td>{s.description}</td>
                    <td>
                      {s.imageURL && (
                        <img
                          src={s.imageURL}
                          alt={s.serviceName}
                          width="50"
                        />
                      )}
                    </td>
                    <td>
                      <button onClick={() => deleteService(s._id)}>
                        Delete
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}

      {/* SLIDER IMAGES SECTION */}
      {activeSection === "slider" && (
        <div className="slider-section">
          <h2>Manage Slider Images</h2>
          <button onClick={() => setActiveSection(null)}>⬅ Back</button>

          <div style={{ marginBottom: "15px" }}>
            <input
              type="file"
              accept="image/*"
              onChange={(e) => setSelectedFile(e.target.files[0])}
            />
            <button onClick={handleUpload}>Upload</button>
          </div>

          <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
            {images.map((url, index) => {
              const fileName = url.split("/").pop();
              return (
                <div key={index} style={{ position: "relative" }}>
                  <img
                    src={url}
                    alt={`slide-${index}`}
                    width="150"
                    style={{ borderRadius: "8px", border: "1px solid #ccc" }}
                  />
                  <button
                    onClick={() => handleDeleteImage(fileName)}
                    style={{
                      position: "absolute",
                      top: "5px",
                      right: "5px",
                      background: "red",
                      color: "white",
                      border: "none",
                      padding: "4px 6px",
                      cursor: "pointer",
                      borderRadius: "4px",
                    }}
                  >
                    X
                  </button>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* USERS SECTION (simple create-user) */}
      {activeSection === "users" && (
        <div className="users-section">
          <h2>Manage Users (Admin)</h2>
          <button onClick={() => setActiveSection(null)}>⬅ Back</button>

          <div style={{ marginTop: 10 }}>
            <h3>Create New User</h3>
            <input
              type="text"
              placeholder="Username (mobile or unique)"
              value={newUserName}
              onChange={(e) => setNewUserName(e.target.value)}
            />
            <input
              type="password"
              placeholder="Password"
              value={newUserPassword}
              onChange={(e) => setNewUserPassword(e.target.value)}
            />
            <input
              type="text"
              placeholder="Mobile (optional)"
              value={newUserMobile}
              onChange={(e) => setNewUserMobile(e.target.value)}
            />
            <input
              type="text"
              placeholder="Email (optional)"
              value={newUserEmail}
              onChange={(e) => setNewUserEmail(e.target.value)}
            />
            <button onClick={createUser}>Create User</button>
            <small style={{ display: "block", marginTop: 6 }}>
              Note: This calls protected endpoint <code>/create-user</code>. Make
              sure server has that implemented.
            </small>
          </div>
        </div>
      )}
    </div>
  );
}

export default Admin;
